def check_langford(seq, n):
    if len(seq) != 2 * n:
        return False, "Length mismatch"

    positions = {}
    for i, val in enumerate(seq):
        if val < 1 or val > n:
            return False, f"Value {val} out of range"
        if val not in positions:
            positions[val] = []
        positions[val].append(i)

    for val in range(1, n + 1):
        if val not in positions:
            return False, f"Value {val} missing"
        if len(positions[val]) != 2:
            return False, f"Value {val} does not appear twice"
        if positions[val][1] - positions[val][0] != val + 1:
            return False, f"Value {val} distance mismatch: {positions[val][1] - positions[val][0]} != {val + 1}"

    return True, "Valid"

seq = [16, 10, 2, 9, 22, 2, 1, 8, 1, 23, 13, 27, 10, 9, 26, 24, 8, 16, 17, 25, 4, 6, 12, 14, 13, 4, 21, 22, 6, 20, 18, 19, 11, 23, 7, 12, 17, 15, 14, 27, 24, 26, 7, 3, 11, 25, 5, 3, 21, 18, 20, 19, 5, 15]
